// Active pool for the game (v2 guide). Starts empty after the v1 corpus was
// frozen into legacy-events.ts on 2026-09-19 — see docs/event-writing-guide-v2.md.
// Real version would extract this from Wikidata (P585/P580 for date, P625 for coordinates).
import DAILY_PACKS_PLAN from "../../data/daily-packs-plan.json";

export type HistoricalEvent = {
  id: string;
  // true when lat/lng/year point at the subject PERSON's birthplace/birth
  // (map pin = where they were born), not a site/event location. See "Person
  // entries" in docs/event-writing-guide-v2.md: whenever this is true, the
  // clue must contain an explicit birth-signal ("born"/"né"/"naît"). Optional
  // here (legacy-events.ts shares this type and predates the convention);
  // scripts/lint-events.mjs requires it on every entry it actually checks
  // (the active v2 pool), which is where this is really enforced.
  pinIsBirthplace?: boolean;
  // Difficulty as WRITTEN, not inferred from source popularity — see
  // "Writing to a target difficulty" in docs/event-writing-guide-v2.md. The
  // writer picks this before drafting (per current pool-stats.md demand) and
  // applies that tier's hint-generosity rules; it may differ from the
  // candidate pool's pageview-based tag in data/candidates-*.json, which is
  // only a notability floor, not a difficulty assignment. Optional here
  // (legacy-events.ts shares this type and predates the field);
  // scripts/lint-events.mjs requires it on every entry in the active v2 pool.
  difficulty?: "easy" | "medium" | "hard";
  // Theme, chosen at drafting time alongside difficulty — same three keys
  // as TOP_CATEGORIES in scripts/fetch-candidates.mjs (machine-stable keys,
  // not the French display labels). Not used by any pack-assembly logic
  // yet (packs are still a random draw — see pickDailyEvents below), but
  // tagged from the start so nothing needs retagging once that logic
  // exists. Optional here (legacy-events.ts shares this type and predates
  // the field); scripts/lint-events.mjs requires it on every entry in the
  // active v2 pool.
  category?: "conflict_politics_society" | "arts_culture" | "science_infrastructure";
  // Finer theme, copied from the source candidate's `subcategory` in
  // data/candidates-*.json at merge time — same keys as SUBCATEGORIES in
  // scripts/fetch-candidates.mjs. build-final-daily-packs.mjs allows at most
  // one event per subcategory in a pack. Optional here (legacy-events.ts
  // shares this type); scripts/lint-events.mjs requires it on every entry in
  // the active v2 pool.
  subcategory?:
    | "war"
    | "rupture"
    | "treaty"
    | "beliefs"
    | "economy"
    | "major_artist"
    | "pioneer"
    | "civil_engineering"
    | "natural_hazard"
    | "archaeological_site"
    | "world_gathering";
  clue: string;
  name: string;
  explanation: string;
  year: number; // negative = BCE
  lat: number;
  lng: number;
  wikipediaTitle: string;
};

